// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public { c = new RoundFactory(); }

    function testFuzz_property(address attackerOrigin, address proxyDeployer, address newImpl) public {
        vm.assume(attackerOrigin != address(0));
        vm.assume(proxyDeployer != address(0));
        vm.assume(newImpl != address(0));
        c.initialize();

        address owner = c.owner();
        vm.assume(owner == address(this));

        ProxyCaller proxy = new ProxyCaller();

        bool okOwnerCall;
        try c.updateRoundImplementation(payable(newImpl)) {
            okOwnerCall = true;
        } catch {
            okOwnerCall = false;
        }

        vm.deal(attackerOrigin, 1 ether);
        vm.prank(attackerOrigin);
        bool okProxiedCall;
        try proxy.callUpdateRoundImplementation(address(c), payable(newImpl)) {
            okProxiedCall = true;
        } catch {
            okProxiedCall = false;
        }

        assertTrue(okOwnerCall && !okProxiedCall);
    }
}

contract ProxyCaller {
    function callUpdateRoundImplementation(address target, address payable impl) external {
        (bool success, ) = target.call(abi.encodeWithSignature("updateRoundImplementation(address)", impl));
        require(success, "forward failed");
    }
}
